import {hasSensitive} from './admin-permissions.mjs';
import {cardMoney,reminderLabels} from './phone-card-finance-contract.mjs';
export function createPhoneCardFinanceWorkspace({api,h,writable,getUser,notify,localTime}){
 const dialog=document.createElement('dialog');dialog.className='editor wide-editor';dialog.setAttribute('aria-label','手机卡充值与余额');document.body.append(dialog);const $=s=>dialog.querySelector(s);let controller,request,timer,serial=0,cardId,tab='recharges',offset=0,root;
 const close=()=>{controller?.abort();request?.abort();clearTimeout(timer);dialog.close();};dialog.addEventListener('cancel',e=>{e.preventDefault();close();});
 window.addEventListener('studio-access-cleared',()=>{controller?.abort();request?.abort();});
 async function load(){
  if(!dialog.open)return;request?.abort();request=new AbortController();const signal=AbortSignal.any([controller.signal,request.signal]),current=++serial;$('#card-money-results').textContent='正在读取记录…';$('#card-money-prev').disabled=true;$('#card-money-next').disabled=true;$('#card-money-filters').hidden=tab!=='recharges';
  try{
   const [s,data]=await Promise.all([api.cardFinanceState(cardId,signal),tab==='balances'?api.cardBalances(cardId,offset,signal):tab==='history'?api.cardRechargeHistory(cardId,root,offset,signal):api.cardRecharges(cardId,{offset,from:$('#card-money-from').value,to:$('#card-money-to').value,q:$('#card-money-q').value,status:$('#card-money-status').value},signal)]);if(signal.aborted||current!==serial)return;
   $('#card-money-name').textContent=s.card.cardCode+' · '+s.card.phoneNumber;$('#card-money-balance').innerHTML=`<b>最近查询余额：${s.balance?s.balance.amountCents===null?'待确认':h(cardMoney(s.balance.amountCents)):'尚未查询'}</b>${s.balance?`<p>查询时点：${h(localTime(s.balance.observedAt))} · 当时号码：${h(s.balance.cardSnapshot.phoneNumber)}</p>`:''}${s.balance&&s.balance.cardSnapshot.phoneNumber!==s.card.phoneNumber?'<p class="save-error">此手记对应旧号码，请按当前号码重新查询核对。</p>':''}<p class="muted">余额来自手记，充值后请按实际查询结果更新。</p>`;
   if(!data.rows.length&&offset>0){offset=Math.max(0,offset-50);await load();return;}
   const action=(kind,title,r)=>`<button class="secondary" data-card-finance-action="${kind}" data-card-id="${h(cardId)}" ${r?`data-recharge-id="${h(r)}"`:''}>${h(title)}</button>`;
   const record=r=>`<article class="observation"><b>${h(r.rechargeDate)} · ${h(cardMoney(r.amountCents))} · ${h(r.rechargeType)}${r.status==='voided'?' · 已作废':''}${tab==='history'?' · 第 '+h(r.version)+' 版':''}</b><p>经办：${h(r.handlerName)} · 付款：${h(r.payerName)} · 归属：${h(r.storeName||'工作室')}</p><p>用途：${h(r.businessPurpose)} · 最初登记号码：${h(r.cardSnapshot.phoneNumber)}</p>${r.sourceChanged?'<p class="save-error">关联原支出已变更，请核对来源；此历史快照保持原样。</p>':''}<details><summary>来源与说明</summary><p>${r.expenseSnapshot?'原支出：'+h(r.expenseSnapshot.description)+' · 当时 '+h(cardMoney(r.expenseSnapshot.amountCents)):'未关联原支出'}</p><p class="preserve-text">充值备注：${h(r.note||'未填写')}</p><p class="preserve-text">登记／修正说明：${h(r.reason)}</p><p>系统录入：${h(r.actor)} · ${h(localTime(r.createdAt))}</p></details>${tab==='recharges'?`<div class="action-row"><button class="text-button" data-recharge-history="${h(r.rechargeId)}">版本历史</button>${writable&&r.status==='recorded'?action('correct','修正',r.rechargeId)+action('void','作废登记',r.rechargeId):''}</div>`:''}</article>`;
   $('#card-money-results').innerHTML=(tab==='recharges'?`<p class="planning-rule">筛选内有效充值：${h(cardMoney(data.summary.amountCents))} · ${data.summary.recordedCount} 笔，另有 ${data.summary.voidedCount} 笔已作废。此汇总不是运营商余额，也不作为额外费用入账。</p>`:'')+data.rows.map(r=>tab==='balances'?`<article class="observation"><b>第 ${r.version} 版 · ${r.amountCents===null?'待确认':h(cardMoney(r.amountCents))}</b><p>实际查询 ${h(localTime(r.observedAt))} · 登记时号码 ${h(r.cardSnapshot.phoneNumber)}</p><p class="preserve-text">${h(r.note)}</p><p>${h(r.actor)} · 录入 ${h(localTime(r.createdAt))}</p></article>`:record(r)).join('')+(data.rows.length?'':'<p class="muted">暂无记录。</p>');$('#card-money-caption').textContent=data.total?`${offset+1}–${offset+data.rows.length} / ${data.total} 条`:'0 条记录';$('#card-money-prev').disabled=offset===0;$('#card-money-next').disabled=offset+50>=data.total;
  }catch(e){if(!signal.aborted)$('#card-money-results').textContent=e.status===404?'当前连接尚未提供充值和余额记录。':e.message;}
 }
 async function open(id){if(!hasSensitive(getUser(),'resources')||!hasSensitive(getUser(),'finance')){notify('充值和余额需要资源与财务两项授权。');return;}cardId=id;tab='recharges';offset=0;controller?.abort();controller=new AbortController();dialog.innerHTML=`<div class="dialog-header"><h2>手机卡充值与余额</h2><button class="icon-button" data-card-money-close aria-label="关闭充值与余额">×</button></div><p id="card-money-name"></p><div id="card-money-balance" class="planning-rule"></div><div class="action-row"><button class="secondary" data-card-money-tab="recharges">充值记录</button><button class="secondary" data-card-money-tab="balances">余额手记历史</button>${writable?`<button class="primary" data-card-finance-action="recharge" data-card-id="${h(id)}">登记充值</button><button class="secondary" data-card-finance-action="balance" data-card-id="${h(id)}">登记查询余额</button>`:''}</div><div id="card-money-filters" class="module-toolbar"><label>开始日期<input id="card-money-from" type="date"></label><label>结束日期<input id="card-money-to" type="date"></label><label>状态<select id="card-money-status"><option value="all">全部记录</option><option value="recorded">有效记录</option><option value="voided">已作废</option></select></label><label class="module-search">搜索<input id="card-money-q" type="search" maxlength="100" placeholder="经办人、付款人、类型、归属或用途"></label></div><div id="card-money-results"></div><div class="pager"><button class="secondary" id="card-money-prev">上一页</button><span id="card-money-caption"></span><button class="secondary" id="card-money-next">下一页</button></div>`;
  $('[data-card-money-close]').onclick=close;dialog.querySelectorAll('[data-card-money-tab]').forEach(el=>el.onclick=()=>{tab=el.dataset.cardMoneyTab;offset=0;load();});for(const id of ['card-money-from','card-money-to','card-money-status'])$('#'+id).onchange=()=>{offset=0;load();};$('#card-money-q').oninput=()=>{offset=0;clearTimeout(timer);timer=setTimeout(load,250);};$('#card-money-prev').onclick=()=>{offset=Math.max(0,offset-50);load();};$('#card-money-next').onclick=()=>{offset+=50;load();};$('#card-money-results').onclick=e=>{const button=e.target.closest('[data-recharge-history]');if(button){root=button.dataset.rechargeHistory;tab='history';offset=0;load();}};if(!dialog.open)dialog.showModal();await load();
 }
 document.addEventListener('click',e=>{const b=e.target.closest('[data-open-card-finance]');if(b)open(b.dataset.openCardFinance);});return {close,refresh:async(id,operation)=>{if(dialog.open&&cardId===id){tab=operation==='balance'?'balances':'recharges';offset=0;await load();}}};
}
export async function renderCardReminderPanel({api,h,user,container,signal}){
 if(!container||!hasSensitive(user,'resources'))return;container.querySelector('[data-phone-reminder-panel]')?.remove();const panel=document.createElement('section');panel.className='work-panel';panel.dataset.phoneReminderPanel='';panel.innerHTML='<h3>手机卡提醒</h3><p class="muted">正在核对当前资源…</p>';container.append(panel);
 try{const data=await api.cardReminders({},signal);if(signal.aborted)return;panel.innerHTML=`<h3>手机卡提醒 · ${data.total} 张需核对</h3><p class="muted">当前到期与使用信息，不随工作日期切换。</p>${data.rows.slice(0,3).map(r=>`<button class="linked-record" data-open-phone-cards data-phone-card-id="${h(r.cardId)}"><b>${h(r.cardCode)}</b><span>${h(r.issues.map(k=>reminderLabels[k]).join('、'))} →</span></button>`).join('')||'<p class="muted">当前没有需核对的手机卡。</p>'}<button class="text-button" data-open-phone-cards data-phone-reminders="true">查看全部及临近日期提醒 →</button>`;}catch(e){if(!signal.aborted)panel.innerHTML='<h3>手机卡提醒</h3><p class="muted">提醒暂未读取，请稍后刷新核对。</p>';}
}
